var _markdown = "\n\n`CFireManager.h` · 全局 `gFireManager`\n\n逻辑帧点 / 灭火。最多 `MAX_NUM_FIRES`（60）。\n\n## 全局管理器 [#全局管理器]\n\n<Api name=\"gFireManager / m_aFires\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      extern CFireManager& gFireManager;\n      // CFire m_aFires[60];\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      #include \"CFireManager.h\"\n      // 用 gFireManager\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 坐标起火 [#坐标起火]\n\n<Api name=\"StartFire（坐标）\">\n  `time` 持续时间相关；`numGenerations` 蔓延代数。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      CFire* StartFire(CVector point, float size, unsigned char arg2, CEntity* creator,\n          unsigned int time, signed char numGenerations, unsigned char arg6);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CVector p = FindPlayerCoors();\n      CFire* f = gFireManager.StartFire(p, 0.8f, 0, nullptr, 7000, 0, 0);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 实体着火 [#实体着火]\n\n<Api name=\"StartFire（实体）\">\n  挂在 ped / 车 / 物体上。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      CFire* StartFire(CEntity* target, CEntity* creator, float size, unsigned char arg3,\n          unsigned int time, signed char numGenerations);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CPed* ped = FindPlayerPed();\n      if (ped) {\n          gFireManager.StartFire(ped, nullptr, 0.8f, 0, 7000, 0);\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 脚本火 [#脚本火]\n\n<Api name=\"StartScriptFire / RemoveScriptFire\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      int StartScriptFire(CVector const& point, CEntity* target, float arg2, unsigned char arg3,\n          signed char numGenerations, int size);\n      void RemoveScriptFire(short fireIndex);\n      bool IsScriptFireExtinguished(short fireIndex);\n      void RemoveAllScriptFires();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      int id = gFireManager.StartScriptFire(p, nullptr, 0.0f, 0, 0, 1);\n      // gFireManager.RemoveScriptFire(id);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 区域灭火 [#区域灭火]\n\n<Api name=\"ExtinguishPoint / ExtinguishPointWithWater\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void ExtinguishPoint(CVector point, float range);\n      bool ExtinguishPointWithWater(CVector point, float range, float fireSizeMp);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      gFireManager.ExtinguishPoint(p, 20.0f);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 查附近火 [#查附近火]\n\n<Api name=\"FindNearestFire / GetNumFiresInRange\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      CFire* FindNearestFire(CVector const& position, bool notBeingExtinguished, bool notScript);\n      unsigned int GetNumFiresInRange(CVector* point, float range);\n      unsigned int GetNumFiresInArea(float cornerA_x, float cornerA_y, float cornerA_z,\n          float cornerB_x, float cornerB_y, float cornerB_z);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CFire* near = gFireManager.FindNearestFire(p, true, false);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n";
